def filter_map_sum(xs):
    mapped = []
    for x in xs:
        if x % 3 == 2:
            mapped.append(x * 5 - 1)

    if len(mapped) >= 2:
        return mapped[0] + mapped[1]
    else:
        return mapped[0] if mapped else 0
