```python
def process_words(text):
    # Split text into words based on single spaces
    words = text.split()

    result = []
    for word in words:
        # Check if length is a multiple of 3
        if len(word) % 3 == 0:
            # Reverse the word
            result.append(word[::-1])
        else:
            # Check if it starts with a vowel
            if word[0] in 'aeiou':
                # Convert to uppercase
                result.append(word.upper())
            else:
                # Leave it unchanged
                result.append(word)

    # Join processed words with '|'
    return '|'.join(result)
```

