def longest_run(xs):
    # Remove every element smaller than -1
    xs = [x for x in xs if x >= -1]
    # If the list is empty, return 0
    if not xs:
        return 0

    # Find the longest run of adjacent equal elements
    max_run = 1
    if len(xs) > 1:
        current_run = 1
        for i in range(1, len(xs)):
            if xs[i] == xs[i-1]:
                current_run += 1
            else:
                max_run = max(max_run, current_run)
                current_run = 1
        max_run = max(max_run, current_run)

    return max_run
