def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Helper function to check divisibility
    def is_divisible(n):
        return n % 3 == 0

    # Start from top-left (0, 0)
    # End at bottom-right (rows-1, cols-1)
    def dp(r, c):
        # Base case: if we are at the end cell, return 1 if divisible, 0 otherwise
        if r == rows - 1 and c == cols - 1:
            return 1 if is_divisible(grid[r][c]) else 0

        # If we are at the start cell, return 1 if divisible, 0 otherwise
        if r == 0 and c == 0:
            return 1 if is_divisible(grid[0][0]) else 0

        # Recursive step
        # We can come from the top or the left
        top = dp(r - 1, c)
        left = dp(r, c - 1)

        return top + left + (1 if is_divisible(grid[r][c]) else 0)

    return dp(0, 0)
