import collections

def bfs_order(n, edges):
    # Build adjacency list
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Perform BFS starting from node 0
    queue = [0]
    visited = {0}
    order = []

    # Sort neighbors in descending order for each node
    def get_neighbors(node):
        # Sort neighbors descending: higher label comes first
        return sorted(adj[node], reverse=True)

    while queue:
        node = queue.pop(0)
        order.append(node)

        # Add unvisited neighbors in sorted order
        for neighbor in get_neighbors(node):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return order
